    """Existing integer amounts were always تومان but had been labelled IRR."""
    for model_name in ("PaymentAttempt", "FinancialLedgerEntry", "Wallet"):
        apps.get_model("shop", model_name).objects.filter(currency="IRR").update(currency="IRT")


